package ru.fifth.horror.client;
import net.minecraft.client.render.*;import net.minecraft.client.render.entity.EntityRenderer;import net.minecraft.client.render.entity.EntityRendererFactory;import net.minecraft.client.util.math.MatrixStack;import net.minecraft.util.Identifier;import net.minecraft.util.math.RotationAxis;import org.joml.Matrix4f;import ru.fifth.horror.FifthMod;import ru.fifth.horror.entity.LiftPanelEntity;
public final class LiftPanelRenderer extends EntityRenderer<LiftPanelEntity>{private static final Identifier TEX=FifthMod.id("textures/entity/lift_panel.png");public LiftPanelRenderer(EntityRendererFactory.Context c){super(c);}@Override public void render(LiftPanelEntity e,float yaw,float tick,MatrixStack ms,VertexConsumerProvider vp,int light){ms.push();ms.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(180-e.getYaw()));ms.translate(-.5,-.5,0);Matrix4f m=ms.peek().getPositionMatrix();VertexConsumer v=vp.getBuffer(RenderLayer.getEntityCutoutNoCull(TEX));v.vertex(m,0,0,0).color(255,255,255,255).texture(0,1).overlay(OverlayTexture.DEFAULT_UV).light(light).normal(ms.peek().getNormalMatrix(),0,0,1).next();v.vertex(m,1,0,0).color(255,255,255,255).texture(1,1).overlay(OverlayTexture.DEFAULT_UV).light(light).normal(ms.peek().getNormalMatrix(),0,0,1).next();v.vertex(m,1,1,0).color(255,255,255,255).texture(1,0).overlay(OverlayTexture.DEFAULT_UV).light(light).normal(ms.peek().getNormalMatrix(),0,0,1).next();v.vertex(m,0,1,0).color(255,255,255,255).texture(0,0).overlay(OverlayTexture.DEFAULT_UV).light(light).normal(ms.peek().getNormalMatrix(),0,0,1).next();ms.pop();super.render(e,yaw,tick,ms,vp,light);}@Override public Identifier getTexture(LiftPanelEntity e){return TEX;}}
